mapper.insert:

    SELECT
        'VITV'||
        LPAD(NVL(TO_NUMBER(SUBSTR(MAX(VIDEO_INTERVIEW_NO), LENGTH('VITV' ) + 1)), 0) + 1, 6, '0')
    FROM VIDEO_INTERVIEW

	INSERT INTO VIDEO_INTERVIEW (
		VIDEO_INTERVIEW_NO
		, INTERVIEW_NO
		, VIDEO_INTERVIEW_START_TIME
		, VIDEO_INTERVIEW_END_TIME
		, VIDEO_INTERVIEW_STATUS
		, VIDEO_INTERVIEW_URL
	) VALUES (
		#{videoInterviewNo}
		, #{interviewNo}
		, TO_DATE(#{videoInterviewStartTime}, 'YYYY-MM-DD HH24:MI')
		, TO_DATE(#{videoInterviewEndTime}, 'YYYY-MM-DD HH24:MI')
		, #{videoInterviewStatus}
		, #{videoInterviewUrl}
	)

mapper.update:
UPDATE VIDEO_INTERVIEW SET 
	VIDEO_INTERVIEW_START_TIME = TO_DATE(#{videoInterviewStartTime}, 'YYYY-MM-DD HH24:MI')
	, VIDEO_INTERVIEW_END_TIME = TO_DATE(#{videoInterviewEndTime}, 'YYYY-MM-DD HH24:MI')
	, VIDEO_INTERVIEW_STATUS = #{videoInterviewStatus}
	, VIDEO_INTERVIEW_URL = #{videoInterviewUrl}
WHERE VIDEO_INTERVIEW_NO = #{videoInterviewNo}
